head.script:
window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());
gtag('config', 'G-VDEZG46KTH');

head.b:skin:
/* ============================================================
   MSDEVBUILD — Premium Editorial Theme
   Tokens
   ============================================================ */
:root{
  --ink:#0E1420;
  --ink-2:#161D2E;
  --ink-line:#2A3348;
  --paper:#F7F6F2;
  --paper-raised:#FFFFFF;
  --line:#E6E3D9;
  --text:#1B2130;
  --text-muted:#5B6478;
  --text-faint:#8992A6;
  --accent:#2451FF;
  --accent-ink:#16307A;
  --accent-soft:#E8EDFF;
  --amber:#FFB020;
  --amber-ink:#7A4E00;
  --radius-lg:18px;
  --radius-md:12px;
  --radius-sm:8px;
  --shadow-sm:0 1px 2px rgba(14,20,32,0.06);
  --shadow-md:0 8px 24px rgba(14,20,32,0.08);
  --shadow-lg:0 24px 60px rgba(14,20,32,0.14);
  --font-display:'Sora',system-ui,sans-serif;
  --font-body:'Inter',system-ui,sans-serif;
  --font-mono:'JetBrains Mono',ui-monospace,monospace;
  --maxw:1180px;
}
[data-theme='dark']{
  --paper:#0E1420;
  --paper-raised:#161D2E;
  --line:#242C40;
  --text:#EDEFF5;
  --text-muted:#A7AFC4;
  --text-faint:#6B7590;
  --accent-soft:#1A2547;
  --ink:#080B12;
  --ink-2:#0E1420;
}

*,*:before,*:after{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;background:var(--paper);color:var(--text);
  font-family:var(--font-body);font-size:16px;line-height:1.65;
  -webkit-font-smoothing:antialiased;transition:background .25s ease,color .25s ease;
  overflow-x:hidden;width:100%;
}
img{max-width:100%;display:block;height:auto}
a{color:var(--accent);text-decoration:none}
a:hover{text-decoration:underline}
h1,h2,h3,h4{font-family:var(--font-display);color:var(--text);line-height:1.2;margin:0 0 .5em}
.container{max-width:var(--maxw);margin:0 auto;padding:0 24px}
.eyebrow{
  font-family:var(--font-mono);font-size:12px;letter-spacing:.04em;
  color:var(--accent);text-transform:uppercase;display:inline-flex;align-items:center;gap:8px;
}
.eyebrow:before{content:'>';color:var(--amber);font-weight:700}
.visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
::selection{background:var(--amber);color:var(--ink)}

/* ============================================================
   Header
   ============================================================ */
.site-header{
  position:sticky;top:0;z-index:60;background:var(--ink);
  border-bottom:1px solid var(--ink-line);
}
.header-inner{
  max-width:var(--maxw);margin:0 auto;padding:0 24px;
  display:flex;align-items:center;justify-content:space-between;height:72px;
}
.brand{display:flex;align-items:center;gap:10px}
.brand-mark{
  font-family:var(--font-mono);font-weight:700;font-size:20px;letter-spacing:-.02em;
  color:#fff;display:flex;align-items:baseline;gap:2px;
}
.brand-mark span{color:var(--amber)}
.brand-tag{
  font-family:var(--font-mono);font-size:11px;color:#8A93AC;
  border-left:1px solid var(--ink-line);padding-left:10px;display:none;
}
@media(min-width:640px){.brand-tag{display:block}}

.main-nav{display:none;align-items:center;gap:22px}
.main-nav a{
  font-family:var(--font-body);font-weight:500;font-size:14.5px;color:#C7CCDB;
}
.main-nav a:hover{color:#fff;text-decoration:none}
@media(min-width:900px){.main-nav{display:flex}}

.header-actions{display:flex;align-items:center;gap:10px}
.icon-btn{
  width:38px;height:38px;border-radius:10px;border:1px solid var(--ink-line);
  background:transparent;color:#C7CCDB;display:flex;align-items:center;justify-content:center;
  cursor:pointer;
}
.icon-btn:hover{border-color:var(--accent);color:#fff}
.icon-btn svg{width:17px;height:17px}

/* mobile menu (checkbox toggle, no JS required) */
#menu-toggle{display:none}
.menu-btn{display:flex}
@media(min-width:900px){.menu-btn{display:none}}
.mobile-nav{
  display:none;background:var(--ink);border-top:1px solid var(--ink-line);
  padding:8px 24px 20px;
}
.mobile-nav a{
  display:block;padding:12px 0;font-family:var(--font-body);color:#DCE0EA;
  border-bottom:1px solid var(--ink-line);font-size:15px;
}
#menu-toggle:checked ~ .mobile-nav{display:block}

.search-panel{display:none;background:var(--ink-2);border-top:1px solid var(--ink-line)}
#search-toggle:checked ~ .search-panel{display:block}
#search-toggle{display:none}
.search-panel form{
  max-width:var(--maxw);margin:0 auto;padding:18px 24px;display:flex;gap:10px;align-items:center;
}
.search-panel input{
  flex:1;background:var(--ink);border:1px solid var(--ink-line);border-radius:10px;
  padding:12px 14px;color:#fff;font-family:var(--font-mono);font-size:14px;
}
.search-panel input::placeholder{color:#5C6480}
.search-panel .search-submit{
  background:var(--amber);color:var(--ink);border:none;border-radius:10px;
  padding:12px 18px;font-weight:700;font-family:var(--font-mono);font-size:13px;cursor:pointer;
}

/* ============================================================
   Announcement bar (promotes blog.msdevbuild.com)
   ============================================================ */
.announce-bar{background:linear-gradient(90deg,var(--accent) 0%,var(--accent-ink) 100%);color:#fff}
.announce-inner{
  max-width:var(--maxw);margin:0 auto;padding:9px 24px;
  display:flex;align-items:center;gap:12px;flex-wrap:wrap;
  font-family:var(--font-body);font-size:13.5px;line-height:1.4;
}
.announce-tag{
  font-family:var(--font-mono);font-size:10.5px;font-weight:700;letter-spacing:.08em;
  text-transform:uppercase;background:var(--amber);color:var(--ink);padding:2px 8px;border-radius:100px;
}
.announce-text{color:#E7EDFF}
.announce-text strong{color:#fff;font-weight:700}
.announce-cta{color:#fff;font-weight:700;text-decoration:underline;text-underline-offset:2px;white-space:nowrap}
.announce-cta:hover{color:var(--amber);text-decoration:underline}
.announce-close{
  margin-left:auto;background:transparent;border:none;color:#fff;font-size:18px;line-height:1;
  cursor:pointer;opacity:.7;padding:2px 6px;border-radius:6px;
}
.announce-close:hover{opacity:1}
@media(max-width:600px){.announce-cta{margin-left:auto}.announce-close{margin-left:6px}}

/* External-link nav item (Blog) */
.main-nav a.nav-ext,.mobile-nav a.nav-ext{color:var(--amber);font-weight:600}
.main-nav a.nav-ext:hover{color:#fff}

/* ============================================================
   Blog highlights — latest from blog.msdevbuild.com (home only)
   ============================================================ */
.blog-highlights{margin:40px auto 8px}
.bh-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:22px;flex-wrap:wrap}
.bh-title{font-family:var(--font-display);font-weight:800;font-size:clamp(22px,3vw,30px);letter-spacing:-.02em;margin:8px 0 0}
.bh-all{font-family:var(--font-mono);font-size:13px;color:var(--accent);white-space:nowrap}
.bh-all:hover{text-decoration:underline}
.bh-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
@media(max-width:900px){.bh-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:600px){.bh-grid{grid-template-columns:1fr}}
.bh-card{
  display:flex;flex-direction:column;gap:10px;background:var(--paper-raised);
  border:1px solid var(--line);border-radius:var(--radius-md);padding:20px;box-shadow:var(--shadow-sm);
  transition:box-shadow .2s ease,border-color .2s ease,transform .2s ease;
}
.bh-card:hover{box-shadow:var(--shadow-md);border-color:var(--accent);transform:translateY(-2px);text-decoration:none}
.bh-tag{
  align-self:flex-start;font-family:var(--font-mono);font-size:10.5px;text-transform:uppercase;
  letter-spacing:.05em;color:var(--accent);background:var(--accent-soft);padding:3px 9px;border-radius:100px;
}
.bh-card-title{font-family:var(--font-display);font-weight:700;font-size:16.5px;line-height:1.32;margin:0;color:var(--text)}
.bh-card-desc{
  font-size:13.5px;color:var(--text-muted);line-height:1.55;margin:0;
  display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;
}
.bh-card-meta{
  margin-top:auto;display:flex;align-items:center;justify-content:space-between;gap:10px;
  font-family:var(--font-mono);font-size:11.5px;color:var(--text-faint);
}
.bh-card-more{color:var(--accent);font-weight:700}
.bh-loading{grid-column:1/-1;padding:30px;text-align:center;color:var(--text-faint);font-family:var(--font-mono);font-size:13px}
.bh-fallback{grid-column:1/-1;padding:24px;text-align:center;color:var(--accent);font-family:var(--font-mono);font-size:13.5px;border:1px dashed var(--line);border-radius:var(--radius-md)}

/* ============================================================
   Hero / Featured
   ============================================================ */
.hero{
  grid-column:1/-1;
  position:relative;background:var(--ink);color:#fff;overflow:hidden;
  border-radius:var(--radius-lg);margin-top:0;margin-bottom:0;
  background-image:
    linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);
  background-size:36px 36px;
}
.hero:after{
  content:'';position:absolute;inset:0;pointer-events:none;z-index:0;border-radius:var(--radius-lg);
  background:radial-gradient(900px 460px at 12% 0%,rgba(36,81,255,.4),transparent 60%),
             radial-gradient(700px 380px at 100% 100%,rgba(255,176,32,.2),transparent 60%);
}
.hero-media{
  position:absolute;inset:0;z-index:0;border-radius:var(--radius-lg);overflow:hidden;
}
.hero-media img{
  width:100%;height:100%;object-fit:cover;opacity:.55;
}
.hero-media:after{
  content:'';position:absolute;inset:0;
  background:linear-gradient(100deg,rgba(14,20,32,.97) 0%,rgba(14,20,32,.88) 38%,rgba(14,20,32,.55) 68%,rgba(14,20,32,.3) 100%);
}
.hero-inner{
  position:relative;z-index:1;
  padding:52px 32px 32px;
}
.hero-eyebrow{font-family:var(--font-mono);color:var(--amber);font-size:12.5px;letter-spacing:.06em;text-transform:uppercase}
.hero-title{
  font-family:var(--font-display);font-weight:800;font-size:clamp(28px,4.6vw,46px);
  letter-spacing:-.02em;margin:14px 0 16px;max-width:740px;color:#fff;line-height:1.08;
}
.hero-title a{color:inherit}
.hero-title a:hover{text-decoration:none;color:var(--amber)}
.hero-excerpt{color:#C7CCDB;font-size:16.5px;max-width:600px;margin:0 0 18px;line-height:1.6}
.hero-author{
  display:flex;flex-wrap:wrap;align-items:center;gap:14px;margin:0 0 20px;
  font-family:var(--font-mono);font-size:12.5px;color:#C7CCDB;
}
.hero-cta{
  display:inline-flex;margin-top:0;align-items:center;gap:8px;background:var(--amber);
  color:var(--ink);font-weight:700;font-family:var(--font-body);font-size:14px;
  padding:12px 20px;border-radius:10px;
}
.hero-cta:hover{text-decoration:none;background:#fff}

/* Highlighted author name — used across hero, cards, single post, sidebar */
.author-highlight{
  color:var(--amber);font-weight:700;
}
.author-badge{
  display:inline-flex;align-items:center;gap:6px;
  font-family:var(--font-mono);font-size:11.5px;font-weight:700;
  color:var(--accent-ink);background:var(--accent-soft);
  padding:4px 10px;border-radius:20px;letter-spacing:.01em;
}
[data-theme='dark'] .author-badge{color:#C7D3FF}
.author-badge:before{content:"\270D";font-size:11px}
.hero-author .author-badge{
  color:var(--amber);background:rgba(255,176,32,.14);
}

/* Stats row — visually part of the hero, not a separate block */
.stats-bar{
  position:relative;z-index:1;border-top:1px solid rgba(255,255,255,.09);
}
.stats-bar-inner{
  padding:20px 32px 28px;
  display:grid;grid-template-columns:repeat(2,1fr);gap:20px;
}
@media(min-width:640px){.stats-bar-inner{grid-template-columns:repeat(4,1fr)}}
.stat-item{text-align:left}
.stat-num{
  font-family:var(--font-display);font-weight:800;font-size:clamp(20px,2.6vw,27px);
  color:#fff;letter-spacing:-.01em;
}
.stat-num span{color:var(--amber)}
.stat-label{font-family:var(--font-mono);font-size:11px;color:#8A93AC;margin-top:3px;text-transform:uppercase;letter-spacing:.03em}

/* Show more articles CTA */
.show-more{
  display:flex;flex-direction:column;align-items:center;gap:12px;text-align:center;
  margin:36px 0 4px;padding:32px 24px;border:1px solid var(--line);border-radius:var(--radius-lg);
  background:var(--paper-raised);
}
.show-more p{color:var(--text-muted);font-size:14px;margin:0}
.show-more-btn{
  display:inline-flex;align-items:center;gap:8px;background:var(--ink);color:#fff;
  font-weight:700;font-size:14px;padding:12px 24px;border-radius:10px;font-family:var(--font-body);
}
.show-more-btn:hover{text-decoration:none;background:var(--accent)}

/* Achievements strip — compact, single row, no redundant description text */
.achievements{
  grid-column:1/-1;
  background:var(--paper-raised);border:1px solid var(--line);border-radius:var(--radius-lg);
}
.achievements-inner{
  padding:24px 28px;
  display:grid;grid-template-columns:1fr;gap:18px;
}
@media(min-width:640px){.achievements-inner{grid-template-columns:repeat(2,1fr);gap:20px 32px}}
@media(min-width:960px){.achievements-inner{grid-template-columns:repeat(4,1fr)}}
.achievement-card{display:flex;align-items:center;gap:12px}
.achievement-icon{
  width:36px;height:36px;flex-shrink:0;border-radius:9px;background:var(--accent-soft);color:var(--accent);
  display:flex;align-items:center;justify-content:center;
}
.achievement-icon svg{width:18px;height:18px}
.achievement-title{font-family:var(--font-display);font-weight:700;font-size:13.5px;color:var(--text)}

/* Certifications & recognition */
.cred-section{grid-column:1/-1}
.cred-inner{padding:0}
.cred-grid{display:flex;flex-wrap:wrap;gap:10px}
.cred-chip{
  font-family:var(--font-mono);font-size:12px;font-weight:600;letter-spacing:.01em;
  background:var(--paper-raised);border:1px solid var(--line);color:var(--text);
  padding:9px 16px;border-radius:20px;box-shadow:var(--shadow-sm);
}

/* Speaking + YouTube two-column showcase */
.showcase-section{grid-column:1/-1}
.showcase-inner{display:grid;grid-template-columns:1fr;gap:36px}
@media(min-width:820px){.showcase-inner{grid-template-columns:1fr 1fr}}

.speak-list{display:flex;flex-direction:column;gap:14px}
.speak-item{
  padding:16px 18px;background:var(--paper-raised);border:1px solid var(--line);
  border-radius:var(--radius-md);box-shadow:var(--shadow-sm);
}
.speak-title{display:block;font-family:var(--font-display);font-weight:700;font-size:14.5px;color:var(--text);margin-bottom:4px}
.speak-desc{display:block;font-size:13px;color:var(--text-muted);line-height:1.5}

.yt-list{display:flex;flex-direction:column;gap:12px;margin-bottom:16px}
.yt-item{
  display:flex;align-items:center;gap:14px;padding:14px 16px;
  background:var(--paper-raised);border:1px solid var(--line);border-radius:var(--radius-md);
  box-shadow:var(--shadow-sm);color:inherit;transition:box-shadow .2s ease,transform .2s ease;
}
.yt-item:hover{box-shadow:var(--shadow-md);transform:translateY(-2px);text-decoration:none;color:inherit}
.yt-icon{width:36px;height:36px;flex-shrink:0;border-radius:9px;background:#FF0000;color:#fff;display:flex;align-items:center;justify-content:center}
.yt-icon svg{width:18px;height:18px}
.yt-title{display:block;font-family:var(--font-display);font-weight:700;font-size:14px;color:var(--text)}
.yt-desc{display:block;font-size:12.5px;color:var(--text-muted);margin-top:2px}
.view-all-link{
  display:inline-flex;align-items:center;gap:6px;font-family:var(--font-mono);font-size:12.5px;
  color:var(--accent);font-weight:600;
}

/* Technical expertise domains */
.expertise-section{grid-column:1/-1}
.expertise-inner{padding:0}
.expertise-grid{display:grid;grid-template-columns:1fr;gap:16px}
@media(min-width:640px){.expertise-grid{grid-template-columns:1fr 1fr}}
@media(min-width:960px){.expertise-grid{grid-template-columns:repeat(4,1fr)}}
.expertise-card{
  padding:22px;background:var(--paper-raised);border:1px solid var(--line);border-radius:var(--radius-lg);
  box-shadow:var(--shadow-sm);display:flex;flex-direction:column;gap:10px;transition:box-shadow .2s ease,transform .2s ease;
}
.expertise-card:hover{box-shadow:var(--shadow-md);transform:translateY(-2px)}
.expertise-title{font-family:var(--font-display);font-weight:700;font-size:15.5px;color:var(--text)}
.expertise-level{display:block;font-size:12.5px;color:var(--accent);font-weight:600}
.expertise-tags{display:block;font-size:12px;color:var(--text-muted);line-height:1.5}

/* Community impact numbers */
.impact-section{grid-column:1/-1}
.impact-inner{
  display:grid;grid-template-columns:repeat(2,1fr);gap:20px;
  padding:32px 28px;background:var(--ink);border-radius:var(--radius-lg);
}
@media(min-width:640px){.impact-inner{grid-template-columns:repeat(3,1fr)}}
@media(min-width:960px){.impact-inner{grid-template-columns:repeat(5,1fr)}}
.impact-item{text-align:center}
.impact-num{font-family:var(--font-display);font-weight:800;font-size:clamp(24px,3vw,32px);color:var(--amber)}
.impact-label{font-family:var(--font-mono);font-size:11px;color:#8A93AC;margin-top:4px;text-transform:uppercase;letter-spacing:.03em}

.repos-section{grid-column:1/-1}
.repos-inner{padding:0}
.repos-section-standalone{
  max-width:var(--maxw);margin:0 auto;padding:56px 24px 72px;
}
.repos-section-standalone .repos-inner{padding:0}
.repos-grid{display:grid;grid-template-columns:1fr;gap:16px}
@media(min-width:640px){.repos-grid{grid-template-columns:1fr 1fr}}
@media(min-width:960px){.repos-grid{grid-template-columns:repeat(3,1fr)}}
.repos-loading{color:var(--text-faint);font-family:var(--font-mono);font-size:13px;grid-column:1/-1}
.repo-card{
  display:flex;flex-direction:column;gap:10px;padding:20px;
  background:var(--paper-raised);border:1px solid var(--line);border-radius:var(--radius-lg);
  box-shadow:var(--shadow-sm);transition:box-shadow .2s ease,transform .2s ease;
}
.repo-card:hover{box-shadow:var(--shadow-md);transform:translateY(-2px)}
.repo-card-head{display:flex;align-items:center;gap:8px}
.repo-card-head svg{width:16px;height:16px;color:var(--text-faint);flex-shrink:0}
.repo-card-name{
  font-family:var(--font-mono);font-weight:600;font-size:14.5px;color:var(--text);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.repo-card:hover .repo-card-name{color:var(--accent)}
.repo-card-desc{font-size:13.5px;color:var(--text-muted);line-height:1.5;flex:1}
.repo-card-topics{display:flex;flex-wrap:wrap;gap:6px}
.repo-topic-chip{
  font-family:var(--font-mono);font-size:10px;font-weight:600;letter-spacing:.02em;
  background:var(--accent-soft);color:var(--accent-ink);padding:3px 9px;border-radius:20px;
}
[data-theme='dark'] .repo-topic-chip{color:#C7D3FF}
.repo-card-meta{
  display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-family:var(--font-mono);font-size:10.5px;color:var(--text-faint);
}
.repo-card-meta span{display:flex;align-items:center;gap:4px}
.repo-lang-dot{width:9px;height:9px;border-radius:50%;background:var(--accent);display:inline-block}

/* GitHub achievement badges */
.gh-badges{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:24px}
.gh-badge{
  font-family:var(--font-mono);font-size:12px;font-weight:600;
  background:var(--accent-soft);color:var(--accent-ink);padding:8px 14px;border-radius:20px;
}
[data-theme='dark'] .gh-badge{color:#C7D3FF}

/* Bottom showcase: Certifications, Speaking/YouTube, Impact (moved to end of page) */
.bottom-section-standalone{
  max-width:var(--maxw);margin:0 auto;padding:72px 24px 72px;
}

/* Testimonials */
.testimonials-section-standalone{
  max-width:var(--maxw);margin:0 auto;padding:0 24px 72px;
}
.testimonials-inner{padding:0}
.testimonial-grid{display:grid;grid-template-columns:1fr;gap:24px;max-width:900px;margin:0 auto}
@media(min-width:760px){.testimonial-grid{grid-template-columns:1fr 1fr}}
.testimonial-card{
  position:relative;padding:32px 28px 28px;background:var(--paper-raised);border:1px solid var(--line);
  border-radius:var(--radius-lg);box-shadow:var(--shadow-sm);display:flex;flex-direction:column;gap:20px;
}
.testimonial-card:before{
  content:"\201C";position:absolute;top:6px;left:20px;font-family:var(--font-display);font-size:64px;
  font-weight:800;color:var(--accent-soft);line-height:1;z-index:0;
}
.testimonial-quote{position:relative;z-index:1;font-size:15px;color:var(--text);line-height:1.7;margin:14px 0 0;font-style:italic}
.testimonial-author{display:flex;align-items:center;gap:12px}
.testimonial-avatar{
  width:44px;height:44px;border-radius:50%;background:var(--ink);color:#fff;flex-shrink:0;
  display:flex;align-items:center;justify-content:center;font-family:var(--font-mono);font-weight:700;font-size:14px;
}
.testimonial-name{display:block;font-family:var(--font-display);font-weight:700;font-size:14px;color:var(--text)}
.testimonial-role{display:block;font-size:12px;color:var(--text-muted);margin-top:2px}

/* ============================================================
   Layout
   ============================================================ */
.layout{
  max-width:var(--maxw);margin:0 auto;padding:44px 24px 72px;
  display:grid;grid-template-columns:1fr;gap:44px;
}
@media(min-width:960px){.layout{grid-template-columns:minmax(0,1fr) 320px}}

.section-head{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:22px;gap:16px}
.section-head h2{font-size:25px;margin:0;letter-spacing:-.01em}
.section-head .view-all{font-family:var(--font-mono);font-size:12.5px;color:var(--text-muted);white-space:nowrap}

/* Post grid & cards */
.post-grid{display:grid;grid-template-columns:1fr;gap:24px}
@media(min-width:620px){.post-grid{grid-template-columns:1fr 1fr}}
@media(min-width:1300px){.post-grid{grid-template-columns:repeat(4,1fr)}}

.post-card{
  background:transparent;overflow:hidden;
  transition:transform .18s ease;
}
.post-card:hover{transform:translateY(-4px)}
.post-card-link{display:flex;flex-direction:column;height:100%;color:inherit}
.post-card-link:hover{text-decoration:none;color:inherit}
.post-thumb{
  display:block;position:relative;aspect-ratio:4/3;overflow:hidden;
  background:var(--accent-soft);border-radius:var(--radius-lg);
  box-shadow:var(--shadow-md);
}
.post-thumb img{width:100%;height:100%;object-fit:cover;transition:transform .4s ease}
.post-card:hover .post-thumb img{transform:scale(1.08)}
.post-cat-badge{
  position:absolute;top:14px;left:14px;z-index:2;
  font-family:var(--font-mono);font-size:10.5px;font-weight:600;letter-spacing:.03em;text-transform:uppercase;
  background:rgba(14,20,32,.82);color:#fff;padding:6px 12px;border-radius:20px;
  -webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);
}
.post-body{padding:16px 4px 4px;display:flex;flex-direction:column;gap:8px;flex:1}
.post-title{
  font-family:var(--font-display);font-size:18px;font-weight:800;letter-spacing:-.01em;
  color:var(--text);display:block;line-height:1.28;
}
.post-card-link:hover .post-title{color:var(--accent)}
.post-meta{
  font-family:var(--font-mono);font-size:11px;color:var(--text-faint);
  display:flex;gap:10px;flex-wrap:wrap;margin-top:auto;align-items:center;
}
.post-meta .author-badge{font-size:10px;padding:3px 8px}

/* Featured card — the newest article in the grid, shown bigger with a taller image */
.post-card-featured{
  grid-column:1/-1;
}
@media(min-width:620px){
  .post-card-featured{grid-column:span 2}
}
@media(min-width:1300px){
  .post-card-featured{grid-column:span 2}
  .post-card-featured .post-card-link{flex-direction:row;gap:24px}
  .post-card-featured .post-thumb{flex:1 1 55%;aspect-ratio:16/10}
  .post-card-featured .post-body{flex:1 1 45%;padding:8px 8px 8px 0;justify-content:center}
}
.post-card-featured .post-thumb{aspect-ratio:16/9}
.post-card-featured .post-title{font-size:24px;line-height:1.22}
.post-card-featured .post-cat-badge{font-size:11px;padding:7px 14px}

/* Full post list (item/all-list pages) variant */
.post-list-row{
  display:grid;grid-template-columns:150px 1fr;gap:20px;padding:22px 0;border-bottom:1px solid var(--line);
}
@media(max-width:520px){.post-list-row{grid-template-columns:1fr}}
.post-list-row .post-thumb{border-radius:var(--radius-md);aspect-ratio:4/3}
.post-list-row .post-title{font-size:19px}

/* Pagination */
.blog-pager{display:flex;justify-content:center;gap:12px;margin-top:44px}
.blog-pager a,.blog-pager span{
  font-family:var(--font-mono);font-size:13px;padding:10px 18px;border-radius:10px;
  border:1px solid var(--line);color:var(--text);
}
.blog-pager a:hover{border-color:var(--accent);color:var(--accent);text-decoration:none}

/* Ad slot */
.ad-slot{
  margin:36px 0;padding:18px;border:1px dashed var(--line);border-radius:var(--radius-md);
  text-align:center;background:var(--paper-raised);overflow:hidden;max-width:100%;
}
.ad-slot .eyebrow{margin-bottom:10px;justify-content:center}
.ad-slot ins,.ad-slot iframe,.ad-slot .adsbygoogle{max-width:100%!important}

/* Defensive: prevent any Google Auto Ads unit from overflowing or overlapping content */
ins.adsbygoogle,.adsbygoogle{max-width:100%!important;overflow:hidden!important}

/* Never allow Auto Ads to inject into the hero banner */
.hero ins.adsbygoogle,.hero .adsbygoogle,
.hero [id^="aswift"],.hero [id^="google_ads"],.hero [id^="div-gpt-ad"],
.hero ins,.hero iframe{display:none!important}

/* ============================================================
   Sidebar
   ============================================================ */
.sidebar{display:flex;flex-direction:column;gap:28px}
.widget-card{
  background:var(--paper-raised);border:1px solid var(--line);border-radius:var(--radius-lg);
  padding:24px;box-shadow:var(--shadow-sm);transition:box-shadow .2s ease;
}
.widget-card:hover{box-shadow:var(--shadow-md)}
.widget-title{
  font-family:var(--font-mono);font-size:11.5px;text-transform:uppercase;letter-spacing:.07em;
  color:var(--text-faint);margin:0 0 16px;
}

.author-card{text-align:left}
.author-photo{width:64px;height:64px;border-radius:50%;object-fit:cover;margin-bottom:14px;border:2px solid var(--accent-soft)}
.author-name{font-family:var(--font-display);font-weight:700;font-size:17px;margin:0;color:var(--amber-ink)}
[data-theme='dark'] .author-name{color:var(--amber)}
.author-role{color:var(--text-muted);font-size:13.5px;margin:2px 0 12px}
.author-bio{font-size:14px;color:var(--text-muted);margin:0 0 16px}
.social-row{display:flex;gap:8px}
.social-row a{
  width:34px;height:34px;border-radius:8px;border:1px solid var(--line);
  display:flex;align-items:center;justify-content:center;color:var(--text-muted);
}
.social-row a:hover{border-color:var(--accent);color:var(--accent);text-decoration:none}
.social-row svg{width:16px;height:16px}

.popular-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:16px}
.popular-item{display:grid;grid-template-columns:32px 1fr;gap:12px;align-items:start}
.popular-num{font-family:var(--font-mono);font-weight:700;color:var(--accent-soft);
  -webkit-text-stroke:1px var(--accent);font-size:20px;line-height:1}
[data-theme='dark'] .popular-num{-webkit-text-stroke:1px var(--amber);color:transparent}
.popular-title{font-size:14px;font-weight:600;color:var(--text);display:block}
.popular-title:hover{color:var(--accent);text-decoration:none}
.popular-meta{font-family:var(--font-mono);font-size:11px;color:var(--text-faint)}

.tag-cloud{display:flex;flex-wrap:wrap;gap:8px}
.tag-cloud a{
  font-family:var(--font-mono);font-size:12px;padding:7px 12px;border-radius:20px;
  background:var(--accent-soft);color:var(--accent-ink);
}
[data-theme='dark'] .tag-cloud a{color:#C7D3FF}
.tag-cloud a:hover{background:var(--accent);color:#fff;text-decoration:none}

.subscribe-box{background:var(--ink);border-radius:var(--radius-lg);padding:24px;color:#fff}
.subscribe-box .widget-title{color:#8A93AC}
.subscribe-box p{font-size:13.5px;color:#C7CCDB;margin:0 0 16px}
.subscribe-box input[type=text],.subscribe-box input[type=email]{
  width:100%;background:var(--ink-2);border:1px solid var(--ink-line);border-radius:10px;
  padding:12px 14px;color:#fff;font-family:var(--font-mono);font-size:13.5px;margin-bottom:10px;
}
.subscribe-box .btn-amber{
  width:100%;background:var(--amber);color:var(--ink);border:none;border-radius:10px;
  padding:12px;font-weight:700;font-family:var(--font-body);font-size:14px;cursor:pointer;
}

/* PopularPosts / Label widget default markup normalization */
.widget-card ul{list-style:none;margin:0;padding:0}
.widget-card .PopularPosts ul li,.widget-card .Label ul li{margin-bottom:10px}

/* ============================================================
   Single Post Page
   ============================================================ */
.post-page-header{background:var(--ink);color:#fff;padding:48px 0 40px}
.post-page-header .container{max-width:840px}
.breadcrumbs{
  font-family:var(--font-mono);font-size:12px;color:#8A93AC;display:flex;flex-wrap:wrap;
  gap:8px;align-items:center;margin-bottom:20px;
}
.breadcrumbs a{color:#C7CCDB}
.breadcrumbs a:hover{color:var(--amber);text-decoration:none}
.breadcrumbs .breadcrumb-current{color:#8A93AC;max-width:280px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.post-page-title{font-size:clamp(28px,4.5vw,42px);color:#fff;font-family:var(--font-display);font-weight:800;letter-spacing:-.02em}
.post-page-meta{
  font-family:var(--font-mono);font-size:12.5px;color:#8A93AC;display:flex;gap:16px;flex-wrap:wrap;margin-top:16px;align-items:center;
}
.post-page-meta b{color:var(--amber)}

/* Read count, like button & share row — post detail page */
.post-engage-bar{
  display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:16px;
  margin:0 0 32px;padding:14px 18px;border:1px solid var(--line);border-radius:var(--radius-md);
  background:var(--paper-raised);
}
.engage-stats{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.engage-stat{
  display:inline-flex;align-items:center;gap:6px;font-family:var(--font-mono);font-size:13px;
  color:var(--text-muted);
}
.engage-stat svg{width:15px;height:15px;flex-shrink:0}
.like-btn{
  display:inline-flex;align-items:center;gap:7px;font-family:var(--font-mono);font-size:13px;font-weight:600;
  color:var(--text-muted);background:transparent;border:1px solid var(--line);border-radius:20px;
  padding:6px 14px;cursor:pointer;transition:all .18s ease;
}
.like-btn svg{width:15px;height:15px;stroke:currentColor;fill:none;transition:fill .18s ease,stroke .18s ease}
.like-btn:hover{border-color:#E0456B;color:#E0456B}
.like-btn.is-liked{color:#E0456B;border-color:#E0456B;background:rgba(224,69,107,.08)}
.like-btn.is-liked svg{fill:#E0456B;stroke:#E0456B}
.like-btn:disabled{cursor:default;opacity:.85}
.like-btn.is-liked svg{animation:msdb-like-pop .35s ease}
@keyframes msdb-like-pop{
  0%{transform:scale(1)}
  45%{transform:scale(1.4)}
  100%{transform:scale(1)}
}
.share-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.share-label{font-family:var(--font-mono);font-size:12px;color:var(--text-faint);margin-right:2px}
.share-btn{
  width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;
  color:#fff;border:none;cursor:pointer;transition:transform .15s ease,opacity .15s ease;flex-shrink:0;
}
.share-btn:hover{transform:translateY(-2px);opacity:.9;text-decoration:none}
.share-btn svg{width:15px;height:15px;fill:currentColor}
.share-twitter{background:#000}
.share-linkedin{background:#0A66C2}
.share-facebook{background:#1877F2}
.share-whatsapp{background:#25D366}
.share-telegram{background:#26A5E4}
.share-copy{background:var(--ink);position:relative}
.share-copy.copied:after{
  content:'Copied!';position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);
  background:var(--ink);color:#fff;font-family:var(--font-mono);font-size:10.5px;padding:4px 9px;
  border-radius:6px;white-space:nowrap;
}
[data-theme='dark'] .share-copy{background:var(--accent)}
@media(max-width:480px){
  .post-engage-bar{flex-direction:column;align-items:flex-start}
}

/* Post reactions (👍🔥💡) — a lighter-weight companion to the like button */
.reaction-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:0 0 32px}
.reaction-label{font-family:var(--font-mono);font-size:12px;color:var(--text-faint);margin-right:2px}
.reaction-btn{
  display:inline-flex;align-items:center;gap:6px;font-family:var(--font-mono);font-size:13px;font-weight:600;
  color:var(--text-muted);background:var(--paper-raised);border:1px solid var(--line);border-radius:20px;
  padding:6px 12px;cursor:pointer;transition:transform .15s ease,border-color .15s ease,background .15s ease;
}
.reaction-btn:hover:not(:disabled){transform:translateY(-2px);border-color:var(--accent)}
.reaction-btn:disabled{cursor:default}
.reaction-btn.is-picked{border-color:var(--amber);background:var(--accent-soft);color:var(--text)}
.reaction-emoji{font-size:15px;display:inline-block}
.reaction-btn.pop .reaction-emoji{animation:msdb-like-pop .35s ease}

/* Series ("Next in this tutorial") navigation */
.series-nav{
  margin:40px 0;padding:20px;border:1px solid var(--line);border-radius:var(--radius-lg);
  background:var(--paper-raised);display:none;
}
.series-nav.has-links{display:block}
.series-nav-title{font-family:var(--font-mono);font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--text-faint);margin:0 0 14px}
.series-nav-links{display:grid;grid-template-columns:1fr 1fr;gap:14px}
@media(max-width:560px){.series-nav-links{grid-template-columns:1fr}}
.series-nav-link{display:none;flex-direction:column;gap:4px;padding:14px 16px;border:1px solid var(--line);border-radius:var(--radius-md);color:var(--text)}
.series-nav-link.visible{display:flex}
.series-nav-link:hover{border-color:var(--accent);color:var(--accent);text-decoration:none}
.series-nav-link.next{text-align:right;align-items:flex-end}
.series-nav-dir{font-family:var(--font-mono);font-size:10.5px;color:var(--text-faint);text-transform:uppercase;letter-spacing:.04em}
.series-nav-title-text{font-family:var(--font-display);font-weight:700;font-size:14.5px;line-height:1.3}

.post-page-body{max-width:840px;margin:0 auto;padding:44px 24px 60px}
.entry-content{font-size:17.5px;line-height:1.85;color:var(--text)}
.entry-content h2{font-size:26px;margin-top:2em}
.entry-content h3{font-size:21px;margin-top:1.6em}
.entry-content p{margin:0 0 1.3em}
.entry-content img{border-radius:var(--radius-md);margin:1.5em 0}
.entry-content a{text-decoration:underline;text-underline-offset:2px}
.entry-content blockquote{
  border-left:3px solid var(--accent);margin:1.6em 0;padding:4px 0 4px 20px;
  color:var(--text-muted);font-style:italic;
}
.entry-content pre{
  background:var(--ink);color:#DCE0EA;padding:18px;border-radius:var(--radius-md);
  overflow-x:auto;font-family:var(--font-mono);font-size:13.5px;line-height:1.6;
  position:relative;
}
.code-copy-btn{
  position:absolute;top:10px;right:10px;z-index:2;
  display:flex;align-items:center;gap:5px;
  font-family:var(--font-mono);font-size:11px;font-weight:600;color:#C7CCDB;
  background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);border-radius:7px;
  padding:5px 10px;cursor:pointer;transition:background .15s ease,color .15s ease;
}
.code-copy-btn:hover{background:rgba(255,255,255,.16);color:#fff}
.code-copy-btn svg{width:12px;height:12px;flex-shrink:0}
.code-copy-btn.copied{background:var(--amber);color:var(--ink);border-color:var(--amber)}
.entry-content code{
  background:var(--accent-soft);color:var(--accent-ink);padding:2px 6px;border-radius:5px;
  font-family:var(--font-mono);font-size:.88em;
}
.entry-content pre code{background:none;color:inherit;padding:0}
.entry-content ul,.entry-content ol{margin:0 0 1.3em;padding-left:1.3em}
.entry-content li{margin-bottom:.4em}

.post-footer-meta{
  display:flex;flex-wrap:wrap;gap:10px;margin-top:36px;padding-top:24px;border-top:1px solid var(--line);
}
.post-footer-meta a{
  font-family:var(--font-mono);font-size:12px;padding:6px 12px;border-radius:20px;
  background:var(--accent-soft);color:var(--accent-ink);
}
[data-theme='dark'] .post-footer-meta a{color:#C7D3FF}
.post-footer-meta a:hover{text-decoration:none;background:var(--accent);color:#fff}

.author-box{
  display:flex;gap:16px;margin-top:40px;padding:22px;border:1px solid var(--line);
  border-radius:var(--radius-lg);background:var(--paper-raised);
}
.author-box img,.author-box .avatar-svg{width:56px;height:56px;border-radius:50%;flex-shrink:0}
.author-box strong{color:var(--amber-ink);font-size:15.5px}
[data-theme='dark'] .author-box strong{color:var(--amber)}

/* Table of contents */
.toc-box:empty{display:none}
.toc-box{
  border:1px solid var(--line);border-radius:var(--radius-md);padding:18px 22px;
  margin:0 0 32px;background:var(--paper-raised);
}
.toc-box .toc-title{
  font-family:var(--font-mono);font-size:11px;text-transform:uppercase;letter-spacing:.06em;
  color:var(--text-faint);margin:0 0 10px;
}
.toc-box ol{margin:0;padding-left:18px}
.toc-box li{margin-bottom:7px;font-size:14px}
.toc-box li.toc-sub{margin-left:16px;font-size:13px;list-style-type:circle}
.toc-box a{color:var(--text)}
.toc-box a:hover{color:var(--accent);text-decoration:none}

/* Related posts */
.related-posts{margin-top:40px;padding-top:24px;border-top:1px solid var(--line)}
.related-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:12px;margin-top:14px}
.related-card{
  display:block;padding:14px 16px;border:1px solid var(--line);border-radius:var(--radius-md);
  font-size:14px;font-weight:600;color:var(--text);
}
.related-card:hover{border-color:var(--accent);color:var(--accent);text-decoration:none}

/* Reading progress bar */
.reading-progress{position:fixed;top:0;left:0;width:100%;height:3px;z-index:70;background:transparent;pointer-events:none}
.reading-progress-bar{height:100%;width:0%;background:linear-gradient(90deg,var(--accent),var(--amber));transition:width .1s linear}

/* Back to top */
.back-to-top{
  position:fixed;bottom:24px;right:92px;width:44px;height:44px;border-radius:50%;
  background:var(--ink);color:#fff;border:none;display:flex;align-items:center;justify-content:center;
  cursor:pointer;box-shadow:var(--shadow-md);opacity:0;pointer-events:none;transform:translateY(10px);
  transition:opacity .2s ease,transform .2s ease,background .2s ease;z-index:2147482999;
}
.back-to-top.visible{opacity:1;pointer-events:auto;transform:translateY(0)}
.back-to-top:hover{background:var(--accent)}
.back-to-top svg{width:18px;height:18px}
@media(max-width:520px){.back-to-top{right:20px;bottom:88px;width:40px;height:40px}}

/* Comments */
#comments{max-width:840px;margin:0 auto;padding:0 24px 60px}
#comments h4{font-family:var(--font-mono);text-transform:uppercase;font-size:13px;letter-spacing:.05em;color:var(--text-faint)}
.comment-block{border-top:1px solid var(--line);padding:18px 0}

/* ============================================================
   Footer
   ============================================================ */
.site-footer{background:var(--ink);color:#C7CCDB;margin-top:60px}
.footer-inner{
  max-width:var(--maxw);margin:0 auto;padding:56px 24px 28px;
  display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:40px;
}
@media(max-width:760px){.footer-inner{grid-template-columns:1fr;gap:32px}}
.footer-inner h5{font-family:var(--font-mono);font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:#8A93AC;margin:0 0 16px}
.footer-brand p{font-size:14px;color:#9199B0;max-width:340px}
.footer-links{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.footer-links a{font-size:14px;color:#C7CCDB}
.footer-links a:hover{color:#fff}
.footer-bottom{
  max-width:var(--maxw);margin:0 auto;padding:22px 24px;border-top:1px solid var(--ink-line);
  display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:12.5px;color:#6B7590;
  font-family:var(--font-mono);
}
.footer-bottom a{color:#8A93AC}

/* Theme toggle */
.theme-toggle{position:relative}
.theme-toggle svg{position:absolute;transition:opacity .2s ease,transform .2s ease}
.icon-moon{opacity:1}
.icon-sun{opacity:0;transform:rotate(-40deg) scale(.6)}
[data-theme='dark'] .icon-moon{opacity:0;transform:rotate(40deg) scale(.6)}
[data-theme='dark'] .icon-sun{opacity:1;transform:rotate(0) scale(1)}

/* Focus visibility */
a:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:2px}

/* FAQ chatbot */
.faqbot{position:fixed;bottom:24px;right:24px;z-index:2147483000}
.faqbot-toggle{
  width:56px;height:56px;border-radius:50%;background:var(--accent);color:#fff;border:none;
  box-shadow:var(--shadow-lg);cursor:pointer;display:flex;align-items:center;justify-content:center;
  position:relative;
}
.faqbot-toggle svg{position:absolute;width:24px;height:24px;transition:opacity .2s ease,transform .2s ease}
.faqbot-toggle .icon-close{opacity:0;transform:scale(.6) rotate(-45deg)}
.faqbot-toggle.open .icon-chat{opacity:0;transform:scale(.6) rotate(45deg)}
.faqbot-toggle.open .icon-close{opacity:1;transform:scale(1) rotate(0)}
.faqbot-panel{
  position:fixed;bottom:90px;right:24px;width:320px;max-height:460px;
  background:var(--paper-raised);border:1px solid var(--line);border-radius:var(--radius-lg);
  box-shadow:var(--shadow-lg);display:flex;flex-direction:column;overflow:hidden;
  opacity:0;pointer-events:none;transform:translateY(10px);transition:opacity .2s ease,transform .2s ease;
}
.faqbot-panel.open{opacity:1;pointer-events:auto;transform:translateY(0)}
.faqbot-header{background:var(--ink);color:#fff;padding:14px 16px}
.faqbot-header strong{display:block;font-family:var(--font-display);font-size:14.5px}
.faqbot-header span{display:block;font-size:11.5px;color:#8A93AC;margin-top:2px}
.faqbot-messages{flex:1;overflow-y:auto;padding:14px 16px;display:flex;flex-direction:column;gap:10px;max-height:220px}
.faqbot-msg{font-size:13.5px;line-height:1.5;padding:10px 12px;border-radius:12px;max-width:88%}
.faqbot-msg.bot{background:var(--accent-soft);color:var(--text);align-self:flex-start;border-bottom-left-radius:2px}
.faqbot-msg.user{background:var(--ink);color:#fff;align-self:flex-end;border-bottom-right-radius:2px}
.faqbot-quick{display:flex;flex-wrap:wrap;gap:6px;padding:0 16px 12px}
.faqbot-quick button{
  font-family:var(--font-mono);font-size:11px;padding:6px 10px;border-radius:20px;
  border:1px solid var(--line);background:transparent;color:var(--text-muted);cursor:pointer;
}
.faqbot-quick button:hover{border-color:var(--accent);color:var(--accent)}
.faqbot-input{display:flex;border-top:1px solid var(--line)}
.faqbot-input input{flex:1;border:none;padding:12px 14px;font-size:13.5px;background:transparent;color:var(--text);font-family:var(--font-body)}
.faqbot-input input:focus{outline:none}
.faqbot-input button{border:none;background:var(--accent);color:#fff;width:44px;font-size:16px;cursor:pointer}
@media(max-width:480px){
  .faqbot{right:16px;bottom:16px}
  .faqbot-toggle{width:52px;height:52px}
  .faqbot-panel{width:calc(100vw - 32px);right:16px;bottom:80px;max-height:70vh}
}

/* Reduced motion */
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}

head.script:
(function(){
  try{
    var saved = localStorage.getItem('msdb-theme');
    var mode = saved || (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
    if(mode === 'dark'){ document.documentElement.setAttribute('data-theme','dark'); }
  }catch(e){}
})();

div.script:
(function(){
  function initEngageBar(){
  try{
    var engageBar = document.getElementById('postEngageBar');
    if(!engageBar) return;

    function gaEvent(name, label){
      if(typeof gtag === 'function'){
        gtag('event', name, {
          event_category: 'engagement',
          event_label: label,
          page_path: window.location.pathname,
          page_title: document.title
        });
      }
    }
    function fmtCount(n){
      n = parseInt(n, 10) || 0;
      if(n >= 1000000) return (n/1000000).toFixed(1).replace(/\.0$/,'') + 'M';
      if(n >= 1000) return (n/1000).toFixed(1).replace(/\.0$/,'') + 'K';
      return String(n);
    }

    // ===================================================================
    // SHARE + COPY LINK — wired up unconditionally, first, so these never
    // depend on Firebase loading/connecting successfully.
    // ===================================================================
    var shareUrl = encodeURIComponent(window.location.href);
    var shareTitle = encodeURIComponent(document.title);
    var links = {
      shareTwitter: 'https://twitter.com/intent/tweet?url=' + shareUrl + '&text=' + shareTitle,
      shareLinkedin: 'https://www.linkedin.com/sharing/share-offsite/?url=' + shareUrl,
      shareFacebook: 'https://www.facebook.com/sharer/sharer.php?u=' + shareUrl,
      shareWhatsapp: 'https://api.whatsapp.com/send?text=' + shareTitle + '%20' + shareUrl,
      shareTelegram: 'https://t.me/share/url?url=' + shareUrl + '&text=' + shareTitle
    };
    var gaLabels = { shareTwitter:'x_twitter', shareLinkedin:'linkedin', shareFacebook:'facebook', shareWhatsapp:'whatsapp', shareTelegram:'telegram' };
    for(var id in links){
      var el = document.getElementById(id);
      if(el){
        el.setAttribute('href', links[id]);
        (function(gaLabel){ el.addEventListener('click', function(){ gaEvent('share_click', gaLabel); }); })(gaLabels[id]);
      }
    }

    var copyBtn = document.getElementById('shareCopy');
    if(copyBtn){
      copyBtn.addEventListener('click', function(){
        var url = window.location.href;
        var done = function(){
          copyBtn.classList.add('copied');
          setTimeout(function(){ copyBtn.classList.remove('copied'); }, 1800);
        };
        if(navigator.clipboard && navigator.clipboard.writeText){
          navigator.clipboard.writeText(url).then(done).catch(function(){ window.prompt('Copy this link:', url); });
        } else {
          window.prompt('Copy this link:', url);
        }
        gaEvent('share_click', 'copy_link');
      });
    }

    // ===================================================================
    // FIREBASE-DEPENDENT FEATURES (views, likes, reactions) — everything
    // below is wrapped so a Firebase failure only disables THIS section,
    // never the share buttons above.
    // ===================================================================
    try{
      // -----------------------------------------------------------------
      // FIREBASE CONFIG — replace every value below with YOUR project's
      // config. Get this from: Firebase Console -> Project Settings ->
      // General -> "Your apps" -> Web app -> SDK setup and configuration.
      // Create a "Realtime Database" (not Firestore) in your project first,
      // and copy its exact databaseURL (region can vary).
      // -----------------------------------------------------------------
      var firebaseConfig = {
        apiKey: "AIzaSyC1oOQOPnd4i-6W0vXkhDHrzRAFYpd0nDk",
        authDomain: "msdevbuild-blog.firebaseapp.com",
        databaseURL: "https://msdevbuild-blog-default-rtdb.asia-southeast1.firebasedatabase.app",
        projectId: "msdevbuild-blog",
        storageBucket: "msdevbuild-blog.firebasestorage.app",
        messagingSenderId: "780750483780",
        appId: "1:780750483780:web:5cdefcdf90f95d910e2711"
      };

      if(!window.firebase || !firebase.apps){
        if(window.console){ console.error('[msdb engage-bar] Firebase SDK did not load — check for ad-blockers/network issues.'); }
        return;
      }
      if(!firebase.apps.length){ firebase.initializeApp(firebaseConfig); }
      var db = firebase.database();

      // Build a stable, Firebase-safe key from this post's URL path.
      // Firebase keys can't contain . # $ [ ] /
      function sanitizePath(path){
        var clean = path.replace(/^\/|\/$/g, '').replace(/[.#$\[\]\/]/g, '_');
        return clean || 'home';
      }
      var postKey  = sanitizePath(window.location.pathname);
      var postRef  = db.ref('posts/' + postKey);
      var viewsRef = postRef.child('views');
      var likesRef = postRef.child('likes');

      var VIEWS_BASELINE = 1000; // new posts start counted from here
      var LIKES_BASELINE = 20;   // new posts start counted from here

      var readNum = document.getElementById('readCountNum');
      var likeNum = document.getElementById('likeCountNum');
      var likeBtn = document.getElementById('likeBtn');

      // Views: atomic increment on every page load, seeded at baseline
      if(readNum){
        viewsRef.transaction(function(current){
          if(current === null){ return VIEWS_BASELINE + 1; }
          return (current || 0) + 1;
        }, function(error, committed, snapshot){
          if(error && window.console){ console.error('[msdb engage-bar] views transaction failed — check Realtime Database rules.', error); }
          if(!error && committed && snapshot){ readNum.textContent = fmtCount(snapshot.val()); }
        });
      }

      // Likes: read current count, seeding baseline if this post is new
      if(likeNum){
        likesRef.transaction(function(current){
          return current === null ? LIKES_BASELINE : current; // seed only, no increment on read
        }, function(error, committed, snapshot){
          if(error && window.console){ console.error('[msdb engage-bar] likes transaction failed — check Realtime Database rules.', error); }
          if(!error && snapshot){ likeNum.textContent = fmtCount(snapshot.val()); }
        });
      }

      // Anti-spam: has this browser already liked this post?
      if(likeBtn && likeNum){
        var likedFlagKey = 'msdb-liked-' + postKey;
        var alreadyLiked = false;
        try{ alreadyLiked = localStorage.getItem(likedFlagKey) === '1'; }catch(e){}
        if(alreadyLiked){
          likeBtn.classList.add('is-liked');
          likeBtn.disabled = true;
        }

        likeBtn.addEventListener('click', function(){
          if(likeBtn.disabled) return;
          likeBtn.disabled = true;
          // Atomic transaction — safe even if many users click at once
          likesRef.transaction(function(current){
            return (current === null ? LIKES_BASELINE : current) + 1;
          }, function(error, committed, snapshot){
            if(error || !committed){ likeBtn.disabled = false; return; }
            likeNum.textContent = fmtCount(snapshot.val());
            likeBtn.classList.add('is-liked');
            try{ localStorage.setItem(likedFlagKey, '1'); }catch(e){}
            gaEvent('like_click', document.title);
          });
        });
      }

    // Reactions (👍🔥💡) — post-level, global counts via the same Firebase connection
    var reactionBar = document.getElementById('reactionBar');
    if(reactionBar){
      var reactionsRef = postRef.child('reactions');
      var reactionBtns = reactionBar.querySelectorAll('.reaction-btn');
      reactionBtns.forEach(function(btn){
        var type = btn.getAttribute('data-reaction');
        var countEl = btn.querySelector('.reaction-count');
        var pickedKey = 'msdb-reacted-' + postKey + '-' + type;

        reactionsRef.child(type).transaction(function(current){
          return current === null ? 0 : current;
        }, function(error, committed, snapshot){
          if(!error && snapshot){ countEl.textContent = fmtCount(snapshot.val()); }
        });

        var alreadyPicked = false;
        try{ alreadyPicked = localStorage.getItem(pickedKey) === '1'; }catch(e){}
        if(alreadyPicked){ btn.classList.add('is-picked'); btn.disabled = true; }

        btn.addEventListener('click', function(){
          if(btn.disabled) return;
          btn.disabled = true;
          reactionsRef.child(type).transaction(function(current){
            return (current || 0) + 1;
          }, function(error, committed, snapshot){
            if(error || !committed){ btn.disabled = false; return; }
            countEl.textContent = fmtCount(snapshot.val());
            btn.classList.add('is-picked', 'pop');
            setTimeout(function(){ btn.classList.remove('pop'); }, 350);
            try{ localStorage.setItem(pickedKey, '1'); }catch(e){}
            gaEvent('reaction_click', type);
          });
        });
      });
    }
    }catch(fbErr){
      // Firebase-dependent features failed (blocked SDK, bad config, or
      // database rules rejecting access) — share/copy above still work fine.
      if(window.console){ console.error('[msdb engage-bar] Firebase features unavailable:', fbErr); }
    }
  }catch(e){ if(window.console){ console.error('[msdb engage-bar]', e); } }
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', initEngageBar);
  } else {
    initEngageBar();
  }
})();

b:if.script:
(function(){
  var container = document.getElementById('seriesNav');
  if(!container) return;
  var labelUrl = container.getAttribute('data-label-url') || '';
  var hereUrl = (container.getAttribute('data-post-url') || window.location.href).split('#')[0].split('?')[0];
  var feedUrl = labelUrl.replace('/search/label/', '/feeds/posts/default/-/');
  if(feedUrl === labelUrl || !feedUrl) return;

  window.msdbSeriesCallback = function(data){
    if(!data || !data.feed || !data.feed.entry) return;
    var entries = data.feed.entry;
    // Sort oldest-first so "next" always means "published later"
    var posts = entries.map(function(entry){
      var link = '';
      for(var j=0;j<entry.link.length;j++){
        if(entry.link[j].rel === 'alternate'){ link = entry.link[j].href; break; }
      }
      return { title: entry.title.$t, url: link, published: entry.published.$t };
    }).filter(function(p){ return p.url; })
      .sort(function(a,b){ return new Date(a.published) - new Date(b.published); });

    var idx = -1;
    for(var i=0;i<posts.length;i++){
      if(posts[i].url.split('#')[0].split('?')[0] === hereUrl){ idx = i; break; }
    }
    if(idx === -1 || posts.length < 2) return;

    var prevEl = document.getElementById('seriesNavPrev');
    var nextEl = document.getElementById('seriesNavNext');
    if(idx > 0){
      prevEl.href = posts[idx-1].url;
      prevEl.querySelector('.series-nav-title-text').textContent = posts[idx-1].title;
      prevEl.classList.add('visible');
    }
    if(idx < posts.length - 1){
      nextEl.href = posts[idx+1].url;
      nextEl.querySelector('.series-nav-title-text').textContent = posts[idx+1].title;
      nextEl.classList.add('visible');
    }
    if(idx > 0 || idx < posts.length - 1){ container.classList.add('has-links'); }
  };
  var s = document.createElement('script');
  s.src = feedUrl + (feedUrl.indexOf('?') === -1 ? '?' : '&') + 'alt=json-in-script&max-results=50&callback=msdbSeriesCallback';
  document.body.appendChild(s);
})();

(function(){
  var container = document.getElementById('relatedPosts');
  var grid = document.getElementById('relatedGrid');
  if(!container || !grid) return;
  var labelUrl = container.getAttribute('data-label-url') || '';
  // Convert the label's HTML search-page URL into Blogger's actual JSON feed URL.
  // Appending ?alt=json-in-script directly to the search page returns an HTML
  // document, not JSON, which breaks the script tag entirely.
  var feedUrl = labelUrl.replace('/search/label/', '/feeds/posts/default/-/');
  if(feedUrl === labelUrl || !feedUrl){
    grid.innerHTML = '';
    return;
  }
  window.msdbRelatedCallback = function(data){
    if(!data || !data.feed || !data.feed.entry){ grid.innerHTML = ''; return; }
    var entries = data.feed.entry;
    var html = '', count = 0;
    var here = window.location.href.split('#')[0].split('?')[0];
    for (var i=0; i<entries.length && count<3; i++){
      var entry = entries[i];
      var title = entry.title.$t;
      var link = '';
      for (var j=0;j<entry.link.length;j++){
        if(entry.link[j].rel === 'alternate'){ link = entry.link[j].href; break; }
      }
      if(!link || link.split('#')[0].split('?')[0] === here) continue;
      var a = document.createElement('a');
      a.className = 'related-card';
      a.href = link;
      a.textContent = title;
      html += a.outerHTML;
      count++;
    }
    grid.innerHTML = html || '<p style="color:var(--text-faint);font-size:14px">No related articles yet.</p>';
  };
  var s = document.createElement('script');
  s.src = feedUrl + (feedUrl.indexOf('?') === -1 ? '?' : '&') + 'alt=json-in-script&max-results=6&callback=msdbRelatedCallback';
  s.onerror = function(){ grid.innerHTML = ''; };
  document.body.appendChild(s);
})();

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
(function(){
  // Blog highlights — latest from blog.msdevbuild.com RSS (homepage only).
  // Lives here (not inline) because this end-of-body block reliably executes.
  (function(){
    var grid = document.getElementById('bhGrid');
    if(!grid){ return; }
    var FEED = 'https://blog.msdevbuild.com/rss.xml';
    var HOME = 'https://blog.msdevbuild.com';
    var MAX = 6, settled = false;
    function esc(s){ var d=document.createElement('div'); d.textContent=(s==null?'':s); return d.innerHTML; }
    function tv(it,t){ var el=it.getElementsByTagName(t)[0]; return el?el.textContent:''; }
    function fmt(s){ var d=new Date(s); return isNaN(d.getTime())?'':d.toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'}); }
    function fallback(){ grid.innerHTML = '<a class="bh-fallback" href="'+HOME+'" target="_blank" rel="noopener">Read the latest articles on blog.msdevbuild.com →</a>'; }
    var timer = setTimeout(function(){ if(settled){return;} settled=true; fallback(); }, 8000);
    try{
      fetch(FEED, {cache:'no-cache'}).then(function(r){ if(!r.ok){ throw 0; } return r.text(); }).then(function(txt){
        if(settled){ return; }
        var doc = new DOMParser().parseFromString(txt, 'application/xml');
        if(doc.getElementsByTagName('parsererror').length){ throw 0; }
        var items = doc.getElementsByTagName('item');
        if(!items.length){ throw 0; }
        var out = [];
        for(var i=0; i<items.length && i<MAX; i++){
          var it = items[i];
          var cats = it.getElementsByTagName('category');
          var cat = cats.length ? cats[0].textContent : '';
          var title = tv(it,'title'), link = tv(it,'link'), desc = tv(it,'description'), date = fmt(tv(it,'pubDate'));
          out.push('<a class="bh-card" href="'+esc(link)+'" target="_blank" rel="noopener">'
            + (cat ? '<span class="bh-tag">'+esc(cat)+'</span>' : '')
            + '<h3 class="bh-card-title">'+esc(title)+'</h3>'
            + (desc ? '<p class="bh-card-desc">'+esc(desc)+'</p>' : '')
            + '<span class="bh-card-meta"><span>'+esc(date)+'</span><span class="bh-card-more">Read →</span></span>'
            + '</a>');
        }
        settled = true; clearTimeout(timer);
        grid.innerHTML = out.join('');
      }).catch(function(){ if(settled){return;} settled=true; clearTimeout(timer); fallback(); });
    }catch(e){ if(!settled){ settled=true; clearTimeout(timer); fallback(); } }
  })();

  // Reading progress bar
  var bar = document.getElementById('readingProgressBar');
  var article = document.getElementById('entryContent');
  function updateProgress(){
    if(!bar) return;
    if(!article){ bar.style.width = '0%'; return; }
    var rect = article.getBoundingClientRect();
    var total = article.offsetHeight - window.innerHeight;
    var scrolled = Math.min(Math.max(-rect.top, 0), Math.max(total, 0));
    var pct = total > 0 ? (scrolled / total) * 100 : 0;
    bar.style.width = pct + '%';
  }
  window.addEventListener('scroll', updateProgress, {passive:true});
  window.addEventListener('resize', updateProgress);
  updateProgress();

  // Back to top
  var topBtn = document.getElementById('backToTop');
  if(topBtn){
    function toggleTopBtn(){
      if(window.scrollY > 400){ topBtn.classList.add('visible'); }
      else { topBtn.classList.remove('visible'); }
    }
    window.addEventListener('scroll', toggleTopBtn, {passive:true});
    topBtn.addEventListener('click', function(){
      window.scrollTo({top:0, behavior:'smooth'});
    });
    toggleTopBtn();
  }

  // Table of contents
  var tocBox = document.getElementById('tocBox');
  if(tocBox && article){
    var headings = article.querySelectorAll('h2, h3');
    if(headings.length >= 3){
      var title = document.createElement('div');
      title.className = 'toc-title';
      title.textContent = 'Contents';
      var list = document.createElement('ol');
      headings.forEach(function(h, i){
        if(!h.id){ h.id = 'toc-heading-' + i; }
        var li = document.createElement('li');
        if(h.tagName === 'H3'){ li.className = 'toc-sub'; }
        var a = document.createElement('a');
        a.href = '#' + h.id;
        a.textContent = h.textContent;
        li.appendChild(a);
        list.appendChild(li);
      });
      tocBox.appendChild(title);
      tocBox.appendChild(list);
    }
  }

  // Reading time estimate
  var readingTimeStat = document.getElementById('readingTimeStat');
  if(readingTimeStat && article){
    var wordCount = (article.textContent || '').trim().split(/\s+/).filter(Boolean).length;
    var minutes = Math.max(1, Math.round(wordCount / 200));
    readingTimeStat.textContent = minutes + ' min read';
  }

  // Copy button on code blocks
  if(article){
    var codeBlocks = article.querySelectorAll('pre');
    codeBlocks.forEach(function(pre){
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'code-copy-btn';
      btn.innerHTML = '<svg fill="none" stroke="currentColor" stroke-width="1.8" viewBox="0 0 24 24"><path d="M9 9h10v10H9zM5 15V5h10"/></svg><span>Copy</span>';
      btn.addEventListener('click', function(){
        var code = pre.querySelector('code');
        var text = (code || pre).textContent || '';
        var done = function(){
          btn.classList.add('copied');
          btn.querySelector('span').textContent = 'Copied!';
          setTimeout(function(){
            btn.classList.remove('copied');
            btn.querySelector('span').textContent = 'Copy';
          }, 1800);
        };
        if(navigator.clipboard && navigator.clipboard.writeText){
          navigator.clipboard.writeText(text).then(done).catch(function(){});
        } else {
          var ta = document.createElement('textarea');
          ta.value = text;
          ta.style.position = 'fixed';
          ta.style.opacity = '0';
          document.body.appendChild(ta);
          ta.select();
          try{ document.execCommand('copy'); done(); }catch(e){}
          document.body.removeChild(ta);
        }
      });
      pre.appendChild(btn);
    });
  }

  // FAQ chatbot
  var toggle = document.getElementById('faqBotToggle');
  var panel = document.getElementById('faqBotPanel');
  var messages = document.getElementById('faqBotMessages');
  var quick = document.getElementById('faqBotQuick');
  var form = document.getElementById('faqBotForm');
  var input = document.getElementById('faqBotInput');

  if(toggle && panel){
    var answers = {
      who: "Suthahar Jegatheesan is a Senior Solutions Architect with 18+ years across Azure, AI and mobile architecture. He has shipped enterprise mobile platforms live in 54 markets, and wrote the Xamarin Q&A Book.",
      topics: "MSDEVBUILD covers Microsoft Azure, AI and Cognitive Services, .NET MAUI, Xamarin, C# and enterprise architecture patterns.",
      contact: "You can reach out via the Contact page linked in the footer, or connect on LinkedIn.",
      mentorship: "Yes &#8212; Suthahar runs msdevbuild blog and the free mentorship for developers."
    };
    var keywordMap = [
      [['who','suthahar','author','architect'], 'who'],
      [['topic','cover','about the blog','azure','a.i.','maui','xamarin',' ai '], 'topics'],
      [['contact','email','reach'], 'contact'],
      [['mentor','training','course','student','internship'], 'mentorship']
    ];

    function addMessage(text, from){
      var div = document.createElement('div');
      div.className = 'faqbot-msg ' + from;
      div.textContent = text;
      messages.appendChild(div);
      messages.scrollTop = messages.scrollHeight;
    }

    function answerFor(text){
      var lower = ' ' + text.toLowerCase() + ' ';
      for(var i=0;i<keywordMap.length;i++){
        var words = keywordMap[i][0];
        for(var j=0;j<words.length;j++){
          if(lower.indexOf(words[j]) !== -1){ return answers[keywordMap[i][1]]; }
        }
      }
      return "I don't have a canned answer for that yet &#8212; please use the Contact page and Suthahar will get back to you directly.";
    }

    if(quick){
      quick.addEventListener('click', function(e){
        var btn = e.target.closest('button[data-q]');
        if(!btn) return;
        var key = btn.getAttribute('data-q');
        addMessage(btn.textContent, 'user');
        addMessage(answers[key], 'bot');
      });
    }

    function sendTypedMessage(){
      if(!input) return;
      var val = input.value.trim();
      if(!val) return;
      addMessage(val, 'user');
      addMessage(answerFor(val), 'bot');
      input.value = '';
    }

    var sendBtn = document.getElementById('faqBotSend');
    if(sendBtn){
      sendBtn.addEventListener('click', sendTypedMessage);
    }
    if(input){
      input.addEventListener('keydown', function(e){
        if(e.key === 'Enter'){
          e.preventDefault();
          sendTypedMessage();
        }
      });
    }
  }
})();
